<?php
require_once(__DIR__ . '/../../config.php');
require_once($CFG->libdir . '/filelib.php'); require_login();
$context=context_system::instance(); require_capability('local/kbacorporate:manageimplementationaudits',$context); $companyid=required_param('companyid',PARAM_INT); $frameworkid=required_param('frameworkid',PARAM_INT); $type=required_param('type',PARAM_ALPHA); require_sesskey(); \local_kbacorporate\local\access::require_full_company_access($companyid,$USER->id); $framework=$DB->get_record('competency_framework',['id'=>$frameworkid],'*',MUST_EXIST);
$competencies=[]; foreach($DB->get_records('competency',['competencyframeworkid'=>$frameworkid],'idnumber ASC,shortname ASC') as $comp){$competencies[]=['code'=>(string)$comp->idnumber,'name'=>(string)$comp->shortname,'description'=>trim(strip_tags((string)$comp->description)),'parent_id'=>(int)$comp->parentid];}
$tools=[];$mappingflat=[];$toolrecords=$DB->get_records_select('local_kbacorp_bms_tool','companyid IN (0,:companyid)',['companyid'=>$companyid],'code ASC'); foreach($toolrecords as $tool){$criteria=[];foreach($DB->get_records('local_kbacorp_bms_crit',['toolid'=>$tool->id],'sortorder ASC,code ASC') as $criterion){$mappings=[];$sql="SELECT bc.*,comp.idnumber,comp.shortname,comp.competencyframeworkid FROM {local_kbacorp_bms_comp} bc JOIN {competency} comp ON comp.id=bc.competencyid WHERE bc.criterionid=:criterionid ORDER BY comp.idnumber ASC";foreach($DB->get_records_sql($sql,['criterionid'=>$criterion->id]) as $map){if((int)$map->competencyframeworkid!==$frameworkid)continue;$one=['competency_code'=>(string)$map->idnumber,'competency_name'=>(string)$map->shortname,'target_level'=>(int)$map->targetlevel,'priority'=>(string)$map->priority,'mandatory'=>!empty($map->required)];$mappings[]=$one;$mappingflat[]=['tool_code'=>(string)$tool->code,'criterion_code'=>(string)$criterion->code,'competency_code'=>(string)$map->idnumber,'target_level'=>(int)$map->targetlevel,'priority'=>(string)$map->priority,'mandatory'=>!empty($map->required)];}$criteria[]=['criterion_code'=>(string)$criterion->code,'name'=>(string)$criterion->name,'section_code'=>(string)$criterion->sectioncode,'section_name'=>(string)$criterion->sectionname,'description'=>(string)$criterion->description,'min_level_description'=>(string)$criterion->minlabel,'max_level_description'=>(string)$criterion->maxlabel,'evidence_required'=>(string)$criterion->evidencehint,'target_score'=>(int)$criterion->targetscore,'weight'=>(int)$criterion->weight,'sortorder'=>(int)$criterion->sortorder,'mandatory'=>!empty($criterion->required),'active'=>!empty($criterion->active),'competencies'=>$mappings];}$tools[]=['tool_code'=>(string)$tool->code,'name'=>(string)$tool->name,'area'=>(string)$tool->area,'scope'=>(int)$tool->companyid===0?'global':'company','company_id'=>(int)$tool->companyid,'source_version'=>(string)$tool->sourceversion,'scale'=>['min'=>0,'max'=>(int)$tool->scalemax],'active'=>!empty($tool->active),'published_version'=>(int)$tool->currentversion,'has_draft'=>!empty($tool->hasdraft),'criteria'=>$criteria];}
$courses=[];$dbman=$DB->get_manager();if($dbman->table_exists(new xmldb_table('competency_coursecomp'))){$sql="SELECT cc.id,cc.courseid,cc.competencyid,c.idnumber AS competency_code,crs.idnumber AS course_code,crs.shortname AS course_shortname,crs.fullname AS course_fullname FROM {competency_coursecomp} cc JOIN {competency} c ON c.id=cc.competencyid JOIN {course} crs ON crs.id=cc.courseid WHERE c.competencyframeworkid=:frameworkid ORDER BY crs.id,c.idnumber";foreach($DB->get_records_sql($sql,['frameworkid'=>$frameworkid]) as $row){$key=(int)$row->courseid;if(!isset($courses[$key])){$courses[$key]=['course_id'=>$key,'course_code'=>(string)$row->course_code,'shortname'=>(string)$row->course_shortname,'fullname'=>(string)$row->course_fullname,'competencies'=>[]];}$courses[$key]['competencies'][]=(string)$row->competency_code;}}
$payload=['schema'=>$type==='tools'?'kba-bms-tools':'kba-bms-master','version'=>'1.0','exported_at'=>gmdate('c'),'company_id'=>$companyid,'framework'=>['idnumber'=>(string)$framework->idnumber,'name'=>(string)$framework->shortname]];if($type==='tools'){$payload['tools']=$tools;$filename='KBA_BMS_TOOLS_'.preg_replace('/[^A-Za-z0-9_-]+/','_',(string)$framework->idnumber).'.json';}else{$payload['competencies']=$competencies;$payload['tools']=$tools;$payload['mappings']=$mappingflat;$payload['courses']=array_values($courses);$filename='KBA_BMS_MASTER_'.preg_replace('/[^A-Za-z0-9_-]+/','_',(string)$framework->idnumber).'.json';}$json=json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$tempdir=make_temp_directory('local_kbacorporate');$temppath=$tempdir.'/'.$filename;file_put_contents($temppath,$json);send_temp_file($temppath,$filename,0,0,false,true,'application/json; charset=utf-8');
